package com.yuvro.todo.controller;

import com.yuvro.todo.config.JwtUtil;
import com.yuvro.todo.entity.User;
import com.yuvro.todo.repository.UserRepository;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.web.bind.annotation.*;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

@RestController
@RequestMapping("/api/auth")
public class AuthController {

    private final UserRepository userRepository;
    private final PasswordEncoder passwordEncoder;
    private final JwtUtil jwtUtil;

    public AuthController(UserRepository userRepository, PasswordEncoder passwordEncoder, JwtUtil jwtUtil) {
        this.userRepository = userRepository;
        this.passwordEncoder = passwordEncoder;
        this.jwtUtil = jwtUtil;
    }

    @PostMapping("/register")
    public ResponseEntity<Map<String, Object>> register(@RequestBody(required = false) Map<String, Object> body) {
        Map<String, Object> response = new HashMap<>();
        if (body == null) {
            response.put("error", "username, email, and password are required");
            return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(response);
        }

        String username = body.get("username") != null ? body.get("username").toString().trim() : "";
        String email = body.get("email") != null ? body.get("email").toString().trim().toLowerCase() : "";
        String password = body.get("password") != null ? body.get("password").toString() : "";

        if (username.isEmpty() || email.isEmpty() || password.isEmpty()) {
            response.put("error", "username, email, and password are required");
            return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(response);
        }

        if (userRepository.existsByUsername(username) || userRepository.existsByEmail(email)) {
            response.put("error", "User or email already exists");
            return ResponseEntity.status(HttpStatus.CONFLICT).body(response);
        }

        String hashedPassword = passwordEncoder.encode(password);
        User user = new User(username, email, hashedPassword);
        user = userRepository.save(user);

        response.put("message", "User registered successfully");
        response.put("user", user.toDict());
        return ResponseEntity.status(HttpStatus.CREATED).body(response);
    }

    @PostMapping("/login")
    public ResponseEntity<Map<String, Object>> login(@RequestBody(required = false) Map<String, Object> body) {
        Map<String, Object> response = new HashMap<>();
        if (body == null) {
            response.put("error", "Email and password are required");
            return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(response);
        }

        String email = body.get("email") != null ? body.get("email").toString().trim().toLowerCase() : "";
        String password = body.get("password") != null ? body.get("password").toString() : "";

        if (email.isEmpty() || password.isEmpty()) {
            response.put("error", "Email and password are required");
            return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(response);
        }

        Optional<User> userOpt = userRepository.findByEmail(email);
        if (userOpt.isEmpty() || !passwordEncoder.matches(password, userOpt.get().getPasswordHash())) {
            response.put("error", "Invalid credentials");
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(response);
        }

        User user = userOpt.get();
        String token = jwtUtil.generateToken(user.getId());

        response.put("token", token);
        response.put("user", user.toDict());
        return ResponseEntity.ok(response);
    }

    @GetMapping("/me")
    public ResponseEntity<Map<String, Object>> getMe(Authentication authentication) {
        if (authentication == null || !(authentication.getPrincipal() instanceof User user)) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(Collections.singletonMap("error", "Authorization token is missing or invalid"));
        }

        Optional<User> freshUser = userRepository.findById(user.getId());
        User currentUser = freshUser.orElse(user);

        return ResponseEntity.ok(Collections.singletonMap("user", currentUser.toDict()));
    }
}

